echo "CPUS=$(grep -c ^processor /proc/cpuinfo)"; for d in /proc/[0-9]*; do pid=${d#/proc/}; [ -r "$d/stat" ] || continue; s=$(cat "$d/stat" 2>/dev/null); [ -n "$s" ] || continue; comm=$(printf '%s' "$s" | sed 's/.*(//; s/).*//'); rest=$(printf '%s' "$s" | sed 's/^.*) //'); set -- $rest; st=${1}; ut=${12}; sm=${13}; nth=${18}; vsz=${21}; rss=${22}; io=$(cat "$d/io" 2>/dev/null); rb=$(printf '%s' "$io" | sed -n 's/^read_bytes:[[:space:]]*//p'); wb=$(printf '%s' "$io" | sed -n 's/^write_bytes:[[:space:]]*//p'); cm=$(cat "$d/cmdline" 2>/dev/null | tr '\0' ' '); [ -z "$cm" ] && cm=$comm; echo "$pid|$comm|$st|$ut|$sm|$nth|$vsz|$rss|${rb:-0}|${wb:-0}|$(printf '%s' "$cm" | cut -c1-120)"; done